//! Black-76 on a forward, and its inverse.
//!
//! Ported from `~/ib-option-viz/src/optionviz/pricing.py`, which is validated
//! against this same snapshot. The tests below pin this port against values
//! generated by running that module directly, so the two provably agree — if
//! they ever diverge, the Python is the arbiter.
//!
//! Black-76 rather than Black-Scholes because the input we can actually recover
//! from the capture is a **forward** (see [`super::parity`]), not a spot plus a
//! rate and a dividend yield. The carry is already inside the forward, which is
//! what makes the resulting vol free of any rate or dividend assumption.

//! `clippy::neg_cmp_op_on_partial_ord` is allowed deliberately throughout this
//! module. `!(x > 0.0)` and `x <= 0.0` are **not** equivalent for `f64`: the
//! first is true for NaN and the second is false. Every negated comparison here
//! guards a degenerate or unsolvable input, and NaN is exactly the input it must
//! catch — rewriting them the way clippy suggests would let NaN through into the
//! pricer.
#![allow(clippy::neg_cmp_op_on_partial_ord)]

/// sqrt(2*pi)
const SQRT_2PI: f64 = 2.5066282746310002;

/// Vol search bracket for the inverter. 500% covers post-crush meme names.
const VOL_LO: f64 = 1e-6;
const VOL_HI: f64 = 5.0;
/// 64 halvings of [1e-6, 5] resolve vol to ~2.7e-19 — far below quote granularity.
const BISECT_ITERS: u32 = 64;

/// Cumulative normal, Hart's double-precision rational approximation.
///
/// Accurate to ~1e-15, far tighter than the bid/ask granularity it is fed.
pub fn norm_cdf(x: f64) -> f64 {
    let xa = x.abs();
    let e = (-0.5 * xa.min(40.0).powi(2)).exp();

    let tail = if xa > 37.0 {
        0.0
    } else if xa < 7.07106781186547 {
        // Inner branch: the rational approximation proper.
        let mut num = 3.526_249_659_989_11e-2 * xa + 0.700_383_064_443_688;
        num = num * xa + 6.373_962_203_531_65;
        num = num * xa + 33.912_866_078_383;
        num = num * xa + 112.079_291_497_871;
        num = num * xa + 221.213_596_169_931;
        num = num * xa + 220.206_867_912_376;
        let mut den = 8.838_834_764_831_84e-2 * xa + 1.755_667_163_182_64;
        den = den * xa + 16.064_177_579_207;
        den = den * xa + 86.780_732_202_946_1;
        den = den * xa + 296.564_248_779_674;
        den = den * xa + 637.333_633_378_831;
        den = den * xa + 793.826_512_519_948;
        den = den * xa + 440.413_735_824_752;
        e * num / den
    } else {
        // Outer branch: continued fraction for the far tail.
        let mut cf = xa + 0.65;
        for k in [4.0, 3.0, 2.0, 1.0] {
            cf = xa + k / cf;
        }
        e / (cf * SQRT_2PI)
    };

    if x <= 0.0 { tail } else { 1.0 - tail }
}

/// Black-76 price on a forward. Returns the undiscounted (forward) value; every
/// caller here uses `df = 1.0`, for the reason given in [`super::parity`].
///
/// Degenerate inputs (`T <= 0` or `vol <= 0`) return intrinsic rather than NaN,
/// which is both correct and what keeps an expiring ladder from poisoning a fit.
pub fn black76(forward: f64, strike: f64, t: f64, vol: f64, is_call: bool) -> f64 {
    let intrinsic = if is_call {
        (forward - strike).max(0.0)
    } else {
        (strike - forward).max(0.0)
    };

    let denom = vol * t.max(0.0).sqrt();
    if !(denom > 0.0) {
        return intrinsic;
    }

    let d1 = ((forward.max(1e-300) / strike.max(1e-300)).ln() + 0.5 * vol * vol * t) / denom;
    let d2 = d1 - denom;

    if is_call {
        forward * norm_cdf(d1) - strike * norm_cdf(d2)
    } else {
        strike * norm_cdf(-d2) - forward * norm_cdf(-d1)
    }
}

/// Invert Black-76 by bisection.
///
/// Returns `None` where no solution exists — price at or below intrinsic, or at
/// or above the ceiling (the forward for a call, the strike for a put). That is
/// a real and common answer on deep wings and wide books, and callers must treat
/// it as "this strike is unusable", **never** as a zero vol or a zero delta.
pub fn implied_vol(price: f64, forward: f64, strike: f64, t: f64, is_call: bool) -> Option<f64> {
    let intrinsic = if is_call {
        (forward - strike).max(0.0)
    } else {
        (strike - forward).max(0.0)
    };
    let ceiling = if is_call { forward } else { strike };

    if !(t > 0.0) || !(price > intrinsic + 1e-9) || !(price < ceiling - 1e-9) {
        return None;
    }

    let (mut lo, mut hi) = (VOL_LO, VOL_HI);
    for _ in 0..BISECT_ITERS {
        let mid = 0.5 * (lo + hi);
        if black76(forward, strike, t, mid, is_call) < price {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    Some(0.5 * (lo + hi))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Values generated by running `optionviz.pricing` directly. Tolerance is
    /// 1e-12 absolute: this is a faithfulness check on the port, not a tolerance
    /// on the maths.
    const EPS: f64 = 1e-12;

    #[test]
    fn norm_cdf_matches_the_python_reference() {
        let cases = [
            (-40.0, 0.0),
            (-8.0, 6.220960520142783e-16),
            (-7.07106781186547, 7.687298944391137e-13),
            (-3.0, 0.001349898031630115),
            (-1.0, 0.15865525393145702),
            (-0.5, 0.30853753872598694),
            (0.0, 0.5),
            (0.5, 0.691462461274013),
            (1.0, 0.841344746068543),
            (3.0, 0.9986501019683699),
            (7.07106781186547, 0.9999999999992313),
            (8.0, 0.9999999999999993),
            (40.0, 1.0),
        ];
        for (x, want) in cases {
            let got = norm_cdf(x);
            assert!(
                (got - want).abs() < EPS,
                "norm_cdf({x}) = {got}, want {want}"
            );
        }
    }

    /// -7.071.. and +7.071.. straddle the branch cut, and both appear above; a
    /// discontinuity there would show up as a failure in the case list, not here.
    /// This pins the symmetry the two branches must jointly preserve.
    #[test]
    fn norm_cdf_is_symmetric_across_the_branch_cut() {
        for x in [0.1, 1.0, 6.5, 7.07106781186546, 7.07106781186548, 9.0, 20.0] {
            let sum = norm_cdf(x) + norm_cdf(-x);
            assert!((sum - 1.0).abs() < 1e-14, "N({x}) + N(-{x}) = {sum}");
        }
    }

    #[test]
    fn black76_matches_the_python_reference() {
        let cases = [
            (100.0, 100.0, 0.25, 0.2, true, 3.987761167674492),
            (100.0, 100.0, 0.25, 0.2, false, 3.987761167674492),
            (100.0, 90.0, 0.25, 0.2, true, 10.712380896073668),
            (100.0, 110.0, 0.25, 0.2, true, 0.9539473918572234),
            (100.0, 90.0, 0.25, 0.2, false, 0.7123808960736682),
            (753.61, 750.0, 0.0958904, 0.145, true, 15.347783306756469),
            (753.61, 760.0, 0.0958904, 0.145, false, 16.989347985319625),
            (98.58, 100.0, 0.1, 0.85, true, 9.920143745230625),
        ];
        for (f, k, t, v, c, want) in cases {
            let got = black76(f, k, t, v, c);
            assert!(
                (got - want).abs() < EPS,
                "black76({f}, {k}, {t}, {v}, {c}) = {got}, want {want}"
            );
        }
    }

    #[test]
    fn degenerate_inputs_price_at_intrinsic() {
        assert_eq!(black76(100.0, 100.0, 0.0, 0.2, true), 0.0);
        assert_eq!(black76(100.0, 95.0, 0.0, 0.2, true), 5.0);
        assert_eq!(black76(100.0, 100.0, 0.25, 0.0, true), 0.0);
        assert_eq!(black76(100.0, 105.0, 0.0, 0.2, false), 5.0);
    }

    /// Put-call parity is the identity the whole pricing stack rests on: the
    /// forward recovered in `parity.rs` is only meaningful if the model that
    /// consumes it obeys `C - P = F - K`.
    #[test]
    fn call_minus_put_equals_forward_minus_strike() {
        for k in [90.0, 100.0, 110.0] {
            let c = black76(100.0, k, 0.25, 0.2, true);
            let p = black76(100.0, k, 0.25, 0.2, false);
            assert!(
                (c - p - (100.0 - k)).abs() < 1e-12,
                "parity broken at K={k}"
            );
        }
    }

    #[test]
    fn implied_vol_round_trips_against_the_python_reference() {
        let cases = [
            (
                3.987761167674492,
                100.0,
                100.0,
                0.25,
                true,
                0.19999999999999934,
            ),
            (
                12.78517706525976,
                100.0,
                90.0,
                0.25,
                true,
                0.3499999999999992,
            ),
            (
                17.161189165666684,
                100.0,
                110.0,
                0.25,
                false,
                0.5499999999999994,
            ),
            (
                15.347783306756469,
                753.61,
                750.0,
                0.0958904,
                true,
                0.14499999999999957,
            ),
        ];
        for (px, f, k, t, c, want) in cases {
            let got = implied_vol(px, f, k, t, c).expect("solvable");
            assert!(
                (got - want).abs() < EPS,
                "implied_vol({px}, {f}, {k}, {t}, {c}) = {got}, want {want}"
            );
        }
    }

    /// The Python returns NaN here; Rust returns None so a caller cannot
    /// accidentally arithmetic its way past an unsolvable strike.
    #[test]
    fn unsolvable_strikes_return_none() {
        assert_eq!(
            implied_vol(0.0, 100.0, 100.0, 0.25, true),
            None,
            "at intrinsic"
        );
        assert_eq!(
            implied_vol(101.0, 100.0, 100.0, 0.25, true),
            None,
            "above the forward"
        );
        assert_eq!(implied_vol(5.0, 100.0, 100.0, 0.0, true), None, "expired");
        assert_eq!(
            implied_vol(4.0, 100.0, 110.0, 0.25, false),
            None,
            "put above its strike"
        );
    }
}
